inline bool settings_install_mouse_hooks(std::vector<void*>* pending=nullptr){auto user=GetModuleHandleW(L"user32.dll");settingsSetCursorAddress=(void*)GetProcAddress(user,"SetCursorPos");settingsClipCursorAddress=(void*)GetProcAddress(user,"ClipCursor");auto a=MH_CreateHook(settingsSetCursorAddress,&settings_set_cursor,reinterpret_cast<void**>(&settingsOriginalSetCursorPos));if(a!=MH_OK)return false;auto b=MH_CreateHook(settingsClipCursorAddress,&settings_clip_cursor,reinterpret_cast<void**>(&settingsOriginalClipCursor));if(b!=MH_OK){MH_RemoveHook(settingsSetCursorAddress);settingsSetCursorAddress=nullptr;return false;}std::vector<void*> addresses{settingsSetCursorAddress,settingsClipCursorAddress};if(!menu_mouse_install(&addresses)){settings_uninstall_mouse_hooks();return false;}if(pending)pending->insert(pending->end(),addresses.begin(),addresses.end());else if(enable_hook_batch(addresses)!=MH_OK){settings_uninstall_mouse_hooks();return false;}return true;}
