inline void settings_close(bool restorePosition=true){if(!settingsOpen.exchange(false))return;menu_mouse_release();managed_end_preview();managed_flush_selection();import_close();if(settingsCapturePowerKey.exchange(false)|settingsCaptureMenuKey.exchange(false)|settingsCapturePageKey.exchange(false)|settingsCaptureCursorKey.exchange(false))++displayPowerRevision;settingsShortcutConflict=false;settingsOriginalClipCursor(&settingsOldClip);if(restorePosition)settingsOriginalSetCursorPos(settingsOldCursor.x,settingsOldCursor.y);menu_mouse_release();menuDock.cancel();settingsClick=false;settingsNeedsSave=true;}
inline void settings_toggle(){cursor_only_release();if(settingsOpen.load()){settings_close();return;}GetClipCursor(&settingsOldClip);GetCursorPos(&settingsOldCursor);settingsPreviousLeft=(GetAsyncKeyState(VK_LBUTTON)&0x8000)!=0;menuDock.cancel();menuDock.held=settingsPreviousLeft;settingsExpanded=false;settingsClick=false;settingsLockscreen=false;homeRescan=true;settingsOpen=true;settingsOriginalClipCursor(nullptr);POINT center{int(settingsOffsetX.load()+480*settingsScale.load()),int(settingsOffsetY.load()+350*settingsScale.load())};if(settingsWindow)ClientToScreen(settingsWindow,&center);settingsOriginalSetCursorPos(center.x,center.y);settingsMouseX=480;settingsMouseY=350;}
