inline void settings_action(int x,int y){if(homeImportActive){import_hit(x,y);return;}if(y==701){if(x>=390)managed_frame_import();return;}if(y==702){int step=x>=845?1:x>=785?10:x>=450?-10:x>=390?-1:0;if(step)managed_edit(6,step);return;}if(x>=850&&y>=20&&y<65){settings_toggle();return;}if(settingsLockscreen.load()){if(y>=410&&y<455){if(x>=390&&x<445)home_duration_adjust(-1);if(x>=450&&x<505)home_duration_adjust(-10);if(x>=785&&x<840)home_duration_adjust(10);if(x>=845&&x<900)home_duration_adjust(1);return;}if(y>=475&&y<520){if(x>=390&&x<555)home_shuffle_mode(0);if(x>=560&&x<725)home_shuffle_mode(1);if(x>=730&&x<895)home_shuffle_mode(2);return;}for(size_t i=0;i<4;++i){int top=150+int(i)*65;if(y>=top&&y<top+45){if(x>=900&&x<938){import_open(i);return;}if(x>=390&&x<440)home_cycle(i,-1);if(x>=845&&x<895)home_cycle(i,1);return;}}if(y>=535&&y<580){if(x>=60&&x<455)homeRescan=true;if(x>=480&&x<900)settingsLockscreen=false;}return;}if(x>=550&&x<820&&y>=25&&y<65){settingsLockscreen=true;homeRescan=true;if(settingsCapturePowerKey.exchange(false)|settingsCaptureMenuKey.exchange(false))++displayPowerRevision;settingsShortcutConflict=false;return;}if(y>=286&&y<322){settingsCaptureCursorKey=false;settingsCapturePageKey=false;if(x>=390&&x<770){settingsCapturePowerKey=false;settingsCaptureMenuKey=true;settingsShortcutConflict=false;++displayPowerRevision;}if(x>=775&&x<900){settingsCapturePowerKey=settingsCaptureMenuKey=false;settingsShortcutConflict=!settings_menu_shortcut(VK_F9,0);++displayPowerRevision;}return;}if(y>=480&&y<520){if(x>=390&&x<555)display_power_mode(0);if(x>=560&&x<725)display_power_mode(1);if(x>=730&&x<895)display_power_mode(2);return;}if(y>=527&&y<563){settingsCaptureCursorKey=false;settingsCapturePageKey=false;if(x>=390&&x<840){settingsCaptureMenuKey=false;settingsCapturePowerKey=true;settingsShortcutConflict=false;++displayPowerRevision;}if(x>=845&&x<900){settingsCapturePowerKey=settingsCaptureMenuKey=false;settingsShortcutConflict=false;display_power_shortcut(0,0);}return;}if(y>=135&&y<180){if(x>=390&&x<555)overlay_theme(0);if(x>=560&&x<725)overlay_theme(1);if(x>=730&&x<895)overlay_theme(2);return;}if(y>=200&&y<237&&!gpsDisplays.empty()){auto n=selectedDisplay.load();if(x>=390&&x<440)display_select((n+gpsDisplays.size()-1)%gpsDisplays.size());if(x>=845&&x<895)display_select((n+1)%gpsDisplays.size());return;}if(y>=245&&y<285){if(x>=390&&x<440)settingsSelected=(settingsSelected+overlayItemCount-1)%overlayItemCount;if(x>=845&&x<895)settingsSelected=(settingsSelected+1)%overlayItemCount;return;}for(int i=0;i<3;++i){int top=325+i*55;if(y>=top&&y<top+40){if(x>=390&&x<445)overlay_adjust(settingsSelected,i,-1);if(x>=450&&x<505)overlay_adjust(settingsSelected,i,-10);if(x>=785&&x<840)overlay_adjust(settingsSelected,i,10);if(x>=845&&x<900)overlay_adjust(settingsSelected,i,1);return;}}if(y>=570&&y<612){if(x>=60&&x<455)overlay_reset(settingsSelected);if(x>=480&&x<900)overlay_reset(-1);}}

inline std::vector<std::pair<std::string,std::string>> managed_splash_choices(){std::vector<std::pair<std::string,std::string>> out{{"copilot/international","International LT / LoneStar T8520"},{"copilot/zonar","Freightliner Cascadia ICUC / Zonar"},{"copilot/t680","Kenworth NavPlus HD / CoPilot"},{"tomtom/cascadia_icc5","Freightliner Cascadia ICC5"},{"tomtom/mack","Mack Infotainment"},{"tomtom/volvo18","Volvo VNL 2018 / VNR Infotainment"},{"garmin/nuvi465t","Garmin Nuvi 465T (3 seconds)"},{"garmin/vnl2014","Volvo VNL 2014 Dynafleet (3 seconds)"},{"garmin/kenworth_navplus","Kenworth NavPlus (5 seconds)"},{"garmin/peterbilt_smartnav","Peterbilt SmartNav (5 seconds)"}};{std::lock_guard<std::mutex> l(carMutex);for(auto& c:carSplashes)if(c.path.filename()!="__off__")out.push_back({(carIsBronco?"bronco/":"")+c.path.filename().u8string(),c.name});}std::error_code ec;for(auto& e:std::filesystem::directory_iterator(managedBase/"BetterGPS_assets/material/ui/device_splashes",std::filesystem::directory_options::skip_permission_denied,ec))if(e.is_regular_file(ec)&&e.path().extension()==".bga")out.push_back({"custom/"+e.path().filename().u8string(),e.path().stem().u8string()});return out;}
inline std::string managed_splash_name(){int i=managedSelected.load();if(i<0)return "75th anniversary";auto d=managed_snapshot(unsigned(i));for(auto& c:managed_splash_choices())if(c.first==d.splash)return c.second;return std::filesystem::u8path(d.splash).stem().u8string();}
inline void managed_splash_cycle(int step){int i=managedSelected.load();if(i<0)return;auto choices=managed_splash_choices();if(choices.empty())return;std::lock_guard<std::mutex> l(managedMutex);auto& d=managedDevices[i];size_t n=0;for(size_t j=0;j<choices.size();++j)if(choices[j].first==d.splash)n=j;d.splash=choices[(n+choices.size()+step)%choices.size()].first;++d.revision;managedDirty=true;++managedRevision;}
inline void managed_splash_imported(int slot,const std::filesystem::path& path){std::lock_guard<std::mutex> l(managedMutex);if(slot<0||slot>=int(managedDeviceCount)||!managedDevices[slot].used)return;auto& d=managedDevices[slot];d.splash="custom/"+path.filename().u8string();d.startup=2;++d.revision;managedDirty=true;++managedRevision;}
inline void managed_splash_import(int slot=-1){int i=slot>=0?slot:managedSelected.load();if(i<0)return;auto d=managed_snapshot(unsigned(i));import_open(4);std::lock_guard<std::mutex> l(homeImport.mutex);homeImport.deviceSlot=i;importDeviceRoot=managedBase/"BetterGPS_assets/material/ui/device_splashes";importDeviceWidth=d.horizontal?1280:360;importDeviceHeight=d.horizontal?800:740;importDeviceSaved=&managed_splash_imported;}
inline void managed_frame_imported(int slot,const std::filesystem::path& path){std::lock_guard<std::mutex> l(managedMutex);if(slot<0||slot>=int(managedDeviceCount)||!managedDevices[slot].used)return;auto& d=managedDevices[slot];d.frameSkin=path.filename().u8string();d.skin=3;++d.revision;managedDirty=true;++managedRevision;}
inline void managed_frame_import(){int i=managedSelected.load();if(i<0)return;import_open(6);std::lock_guard<std::mutex> l(homeImport.mutex);homeImport.deviceSlot=i;importDeviceRoot=managed_frame_root();importDeviceSaved=&managed_frame_imported;}
inline int managed_car_splash_slot(){for(size_t i=0;i<gpsDisplays.size();++i)if(ford_console_id(gpsDisplays[i].id)&&display_vehicle_matches(gpsDisplays[i],managed_vehicle()))return managed_for_known(i);return -1;}
inline std::string managed_car_splash_name(int slot){auto d=managed_snapshot(unsigned(slot));if(!d.startup)return "OFF";if(d.startup==1)return "Lock screen";for(auto& c:managed_splash_choices())if(c.first==d.splash)return c.second;return std::filesystem::u8path(d.splash).stem().u8string();}
inline void managed_car_splash_cycle(int slot,int step){auto choices=managed_splash_choices();choices.push_back({"__off__","OFF"});std::lock_guard<std::mutex> lock(managedMutex);auto& d=managedDevices[slot];size_t n=choices.size()-1;if(d.startup)for(size_t j=0;j<choices.size();++j)if(choices[j].first==d.splash)n=j;d.splash=choices[(n+choices.size()+step)%choices.size()].first;d.startup=d.splash=="__off__"?0:2;++d.revision;managedDirty=true;++managedRevision;}
inline ManagedDevice managed_display_options(){if(managedSelected>=0)return managed_snapshot(unsigned(managedSelected.load()));ManagedDevice d;if(!gpsDisplays.empty()){auto& current=gpsDisplays[std::min(selectedDisplay.load(),gpsDisplays.size()-1)];d.horizontal=current.layout=="horizontal";d.skin=d.horizontal?1:0;d.startup=d.horizontal?2:1;d.style=int(displayStyleIndex.load());}return d;}


